792	                    len: chunk_len as u32,
793	                    visible: true,
794	                    deletions: Default::default(),
795	                    max_undos: Default::default(),
796	                };
797	                insertions.push(InsertionFragment::new(&fragment), ());
798	                fragments.push(fragment, &None);
